const charDefs=[
 ['jane','Jane Eyre',[],'An orphaned, observant, and morally independent girl who becomes a teacher and governess while insisting that love cannot cost her self-respect.','townsend-1',true],
 ['rochester','Edward Fairfax Rochester',[],'The master of Thornfield, intellectually restless and emotionally forceful, whose concealed marriage makes honesty the condition of any future with Jane.','townsend-2',true],
 ['mrs-reed','Mrs Sarah Reed',[],'Jane’s widowed aunt, who protects her own children and treats the dependent orphan as an unwelcome burden.','portrait-lady-1',false],
 ['john-reed','John Reed',[],'Mrs Reed’s indulged son, whose childhood cruelty matures into waste, debt, and ruin.','reed-scene',false],
 ['bessie','Bessie Lee',[],'The Gateshead nursemaid whose songs, stories, rebukes, and occasional tenderness give Jane her first imperfect affection.','townsend-3',true],
 ['lloyd','Mr Lloyd',[],'The Reed household apothecary who listens seriously to Jane and recommends that she be sent to school.','portrait-gentleman-1',true],
 ['brocklehurst','Mr Brocklehurst',[],'Lowood’s severe treasurer and religious authority, using proclaimed humility to justify deprivation and public shame.','townsend-4',true],
 ['helen','Helen Burns',[],'Jane’s thoughtful Lowood friend, whose endurance, learning, and faith offer a philosophy Jane admires without wholly adopting.','townsend-5',false],
 ['temple','Miss Maria Temple',[],'Lowood’s humane superintendent and teacher, who feeds, hears, and publicly clears Jane.','townsend-6',true],
 ['scatcherd','Miss Scatcherd',[],'A Lowood teacher whose strict attention to Helen’s faults exposes the school’s punitive habits.','townsend-7',true],
 ['adele','Adèle Varens',[],'Rochester’s lively French ward and Jane’s pupil, eager for attention, presents, performance, and affection.','townsend-8',true],
 ['fairfax','Mrs Alice Fairfax',[],'Thornfield’s housekeeper, a courteous relation of the Rochester family who welcomes Jane but knows only part of the house’s secret.','portrait-lady-2',true],
 ['grace','Grace Poole',[],'A well-paid servant whose guarded work on Thornfield’s third floor provides a plausible name for unexplained sounds.','townsend-9',true],
 ['bertha','Bertha Antoinetta Mason Rochester',[],'Rochester’s wife, confined at Thornfield after years of severe illness and presented through a narrative controlled by those who imprison her.','garrett-bertha',false],
 ['blanche','Blanche Ingram',[],'An accomplished and status-conscious guest whose apparent courtship with Rochester makes Jane confront class and economic inequality.','townsend-10',true],
 ['mason','Richard Mason',[],'Bertha’s brother from Spanish Town, whose arrival and later testimony make Rochester’s hidden marriage legally unavoidable.','townsend-11',true],
 ['briggs','Mr Briggs',[],'A London solicitor who brings documentary proof of Rochester’s marriage and later administers Jane’s inheritance.','portrait-gentleman-2',true],
 ['st-john','St John Eyre Rivers',[],'A disciplined clergyman whose vocation, self-command, and imperial mission cannot accommodate Jane as an equal emotional partner.','townsend-12',true],
 ['diana','Diana Rivers',[],'St John’s learned, warm sister, who welcomes Jane’s mind and later becomes her cousin and chosen family.','townsend-13',true],
 ['mary','Mary Rivers',[],'Diana’s quieter sister, sharing intellectual companionship, household work, and the restored family at Moor House.','townsend-14',true],
 ['hannah','Hannah',[],'The Rivers household servant, initially suspicious of a destitute stranger but willing to revise her judgment.','townsend-15',true],
 ['rosamond','Rosamond Oliver',[],'The beautiful and generous daughter of Morton’s wealthy patron, drawn to St John despite his refusal of domestic happiness.','townsend-16',true],
]
